diff --git a/lib/src/agents/instruction_processor.dart b/lib/src/agents/instruction_processor.dart
index 5ef487e..abcb9a7 100644
--- a/lib/src/agents/instruction_processor.dart
+++ b/lib/src/agents/instruction_processor.dart
@@ -18,8 +18,14 @@ library;
 import 'dart:io';

 /// Matches relative or absolute file paths with known extensions.
+///
+/// Path segments may contain dots (`/home/runner/.dmtools/packs/
+/// story_development-0.1.18/...md`) — pack paths on runners always do —
+/// so the charset includes `.` between separators. The extension anchor
+/// stays pinned to the known list, and the leading boundary (`/`, `./`,
+/// `../`) keeps ordinary prose with dots out.
 final RegExp _filePathRegExp = RegExp(
-  r'\.{0,2}/[\w/-]+\.(?:md|txt|json|yaml|yml)',
+  r'(?<![:/\w])\.{0,2}/[\w./-]+\.(?:md|txt|json|yaml|yml)\b',
 );

 /// Matches GitHub pull-request URLs (captures owner, repo, number).
diff --git a/test/agents/instruction_processor_packpath_test.dart b/test/agents/instruction_processor_packpath_test.dart
new file mode 100644
index 0000000..9b248f6
--- /dev/null
+++ b/test/agents/instruction_processor_packpath_test.dart
@@ -0,0 +1,40 @@
+import 'dart:io';
+import 'package:test/test.dart';
+import 'package:dmtools/src/agents/instruction_processor.dart';
+
+void main() {
+  late Directory dir;
+  setUp(() {
+    dir = Directory.systemTemp.createTempSync('ip_pack');
+    Directory(
+            '${dir.path}/.dmtools/packs/story_development-0.1.18/instructions/common')
+        .createSync(recursive: true);
+    File('${dir.path}/.dmtools/packs/story_development-0.1.18/instructions/common/agent_task_preamble.md')
+        .writeAsStringSync('PREAMBLE CONTENT');
+    File('${dir.path}/notes.md').writeAsStringSync('NOTES');
+  });
+  tearDown(() => dir.deleteSync(recursive: true));
+
+  test('absolute pack path with dots in segments is embedded', () {
+    final p = InstructionProcessor(workingDirectory: dir.path);
+    final prompt =
+        'Senior Developer Engineer\n${dir.path}/.dmtools/packs/story_development-0.1.18/instructions/common/agent_task_preamble.md';
+    final out = p.process(prompt);
+    expect(out, contains('PREAMBLE CONTENT'));
+    expect(out, contains('<file path="'));
+  });
+
+  test('github/readme URLs are not treated as file paths', () {
+    final p = InstructionProcessor(workingDirectory: dir.path);
+    final out = p.process(
+        'see https://github.com/foo/bar/pull/1 and https://x.com/readme.md ok');
+    expect(out, isNot(contains('<file path="https')));
+    expect(out, contains('[github-pr:foo/bar#1]'));
+  });
+
+  test('relative inline reference still embeds', () {
+    final p = InstructionProcessor(workingDirectory: dir.path);
+    final out = p.process('read ./notes.md please');
+    expect(out, contains('NOTES'));
+  });
+}
