import 'dart:io';

final RegExp re = RegExp(
  r'(?<![:/\w])\.{0,2}/[\w./-]+\.(?:md|txt|json|yaml|yml)\b',
);

void check(String label, String input, List<String> expected) {
  final got = re.allMatches(input).map((m) => m.group(0)!).toList();
  final ok = got.toString() == expected.toString();
  print('${ok ? "PASS" : "FAIL"} [$label] input=$input -> $got');
}

void main() {
  // The fixed scenario
  check('pack path', 'x\n/home/r/.dmtools/packs/story_development-0.1.18/i/c/a.md',
      ['/home/r/.dmtools/packs/story_development-0.1.18/i/c/a.md']);
  // URL boundaries
  check('url readme', 'see https://x.com/readme.md ok', []);
  check('url trailing-dot host', 'see https://x.com./readme.md ok', ['/readme.md']);
  check('url with port', 'http://host:8080/file.md', []);
  check('file scheme', 'file:///etc/config.yaml', []);
  check('url gh non-pr', 'https://github.com/o/r/blob/main/lib.dart', []);
  // Punctuation / prose
  check('sentence end', 'Read /tmp/a.md. Then rest', ['/tmp/a.md']);
  check('ellipsis path', '.../a.md and ./b.md', ['./a.md', './b.md']);
  check('comma sep', '/a.md,/b.md', ['/a.md', '/b.md']);
  check('md link abs', 'see [docs](/abs/dir/file.md) now', ['/abs/dir/file.md']);
  check('md link rel', 'see [docs](./rel.md) now', ['./rel.md']);
  check('backtick', 'open `/x/y.md` now', ['/x/y.md']);
  check('json field', '{"p":"/a/b.json"}', ['/a/b.json']);
  check('mdx not matched', 'read /f/file.mdx now', []);
  check('ext then colon', 'path /f/a.md: see', ['/f/a.md']);
  check('start of string', '/abs/start.md x', ['/abs/start.md']);
  check('win drive', 'C:/Users/x/file.md', []);
  check('double slash', '//etc/x.md', ['//etc/x.md']);
  check('deep dots', '/a.b.c/d.e/f.md', ['/a.b.c/d.e/f.md']);
  check('trailing slash-dot', '/a./b.md', ['/a./b.md']);
  check('two dots rel', '../up/x.yml', ['../up/x.yml']);
  check('version then slash', 'v1.2.3/notes.md and ./ok.md', ['./ok.md']);
  check('three-dot url path', 'https://x.com/a.b/file.md', []);
  check('prose dot space path', 'end of sentence. /tmp/real.md', ['/tmp/real.md']);
  // Non-existent extensions unchanged behavior
  check('no ext', 'see ./README and /x/file', []);
}

