import 'package:test/test.dart';

void main() {
  filePathEmbeddingTests();
  filePathEdgeCaseTests();
  jiraKeyAnnotationTests();
  urlAnnotationTests();
  multipleReferencesTests();
  noReferencesTests();
  nonExistentFileTests();
