    expect(
      match.group(2),
      matches(RegExp(r'^[0-9a-f]{40}$')),
      reason: 'the factory home pin must be an immutable full SHA '
          '(got ${match.group(2)})',
    );
    final refLine = RegExp(r'factory_ref:\s*([0-9a-f]{40})').firstMatch(yml);
    expect(
